window.AUTH=window.AUTH||{};window.AUTH["19-351"]={"d":"19-351","id":"2020/19-351","n":"Federal Republic of Germany v. Philipp","briefs":[{"k":"petitioner","label":"Brief of petitioners Federal Republic of Germany, et al.","date":"2020-09-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-351/153210/20200904172357322_2020-09-04%20Brief%20of%20Petitioners.pdf","side":"pet","n":68},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-09-11","url":"https://www.supremecourt.gov/DocketPDF/19/19-351/153827/20200911202901200_19-351tsacUnitedStates.pdf","side":"us","n":46},{"k":"respondent","label":"Brief of respondents Alan Philipp, et al.","date":"2020-10-22","url":"https://www.supremecourt.gov/DocketPDF/19/19-351/158522/20201022151404770_Respondents%20Brief.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioners Federal Republic of Germany, et al.","date":"2020-11-23","url":"https://www.supremecourt.gov/DocketPDF/19/19-351/161589/20201123155323086_2020-11-23%20Reply%20Brief.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-351_o7jp.pdf","tr":true,"items":[{"t":"case","label":"Abelesz v. Magyar Nemzeti Bank","cite":"692 F.3d 661","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/692/661/","ar":1,"by":{"0":"21, 34, 53","1":"18","2":"12, 27","3":"20"}},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"sum":"The Court found that using a telephone to make a misdemeanor drug purchase does not facilitate the felony of drug distribution.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Bakalian v. Central Bank of Republic of Turkey","cite":"932 F.3d 1229","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/932/1229/","by":{"0":"34","1":"27"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"op":3,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"0":"25, 26, 43","1":"11, 16, 28","2":"30, 31, 51"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne International Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"op":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"0":"passim","1":"8, 22, 23, 24, 27, 29, 24","2":"11, 26, 27, 30","3":"passim"}},{"t":"case","label":"Daimler AG v. Bauman","cite":"134 S. Ct. 746","y":2014,"id":"2013/11-965","sc":1,"sum":"The Court held the judiciary did not have jurisdiction over DaimlerChrysler AG in California because the conduct in question was not in the state.","sumSrc":"Oyez","by":{"0":"43","2":"51"}},{"t":"case","label":"de Sanchez v. Banco Central de Nicaragua","cite":"770 F.2d 1385","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/770/1385/","sum":"Describing the customary international law of human rights.","sumSrc":"brief:0","by":{"0":"18, 29","1":"13"}},{"t":"case","label":"Dolan v. U.S. Postal Service","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"ar":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"0":"27, 30","3":"10"}},{"t":"case","label":"F. Palicio y Compania, S. A. v. Brush","cite":"256 F. Supp. 481","y":1966,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./256/481/","op":1,"sum":"Interpreting the Hickenlooper Amendment to displace Sabbatino but dismissing the suit on the ground that “confiscations by a state of the property of its own nationals, no matter how flagrant . . . , do not constitute violations of international law”.","sumSrc":"opinion","by":{"0":"26","1":"17","2":"32"}},{"t":"case","label":"F.A.A. v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"F.C.C. v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"0":"28","3":"8"}},{"t":"case","label":"Fischer v. Magyar Allamvasutak Zrt.","cite":"777 F.3d 847","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/847/","ar":1,"by":{"0":"17, 34, 44, 53","2":"42, 43"}},{"t":"case","label":"Forest Grove School Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"22, 33","3":"5"}},{"t":"case","label":"Hilton v. Guyot","cite":"159 U.S. 113","y":1895,"id":"scdb/1894-250","sc":1,"sum":"A citizen and resident of this country, who has his principal place of business here, but has an agent in a foreign country, and is accustomed to purchase and store large quantities of goods there, and, in a suit brought against him by a citizen and in a court of that country, appears and defends with the sole object of preventing his property within the jurisdiction, but not in the custody of that court, from being …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42","2":"38, 48"}},{"t":"case","label":"Iowa Mutual Insurance Co. v. LaPlante","cite":"480 U.S. 9","y":1987,"id":"1986/85-1589","sc":1,"sum":"Respondent employee (hereafter respondent) of a ranch located on the Blackfeet Indian Reservation and owned by Indians, brought suit in Blackfeet Tribal Court seeking compensation from the ranch for personal injuries respondent suffered when the cattle truck he was driving \"jackknifed,\" and seeking compensatory and punitive damages from petitioner, the ranch's insurer, for its alleged bad-faith refusal to settle the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Jams v. International Finance Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"sum":"The International Organizations Immunities Act of 1945 affords international organizations the same immunity from suit that foreign governments enjoy today under the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"44, 45","1":"26"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"28","2":"15"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"op":2,"sum":"Interpreting Alien Tort Statute so as not to “adopt an interpretation of U. S. law that carries foreign policy consequences not clearly intended by the political branches”.","sumSrc":"opinion","by":{"0":"39, 44, 45, 54","2":"50, 51"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"0":"27, 33, 34","3":"11"}},{"t":"case","label":"Maslenjak v. United States","cite":"137 S. Ct. 1918","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"McDermott International, Inc. v. Wilander","cite":"498 U.S. 337","y":1991,"id":"1990/89-1474","sc":1,"sum":"One need not aid in the navigation of a vessel in order to qualify as a \"seaman\" under the Jones Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"22","3":"7"}},{"t":"case","label":"Mezerhane v. Republica Bolivariana de Venezuela","cite":"785 F.3d 545","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/545/","ar":1,"by":{"0":"18","1":"13","2":"27","3":"20"}},{"t":"case","label":"Mujica v. AirScan Inc.","cite":"771 F.3d 580","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/771/580/","by":{"0":"43, 46, 47","2":"46, 47, 48","3":"22"}},{"t":"case","label":"Murray v. The Schooner Charming Betsy","cite":"6 U.S. 64","y":1804,"id":"scdb/1804-007","sc":1,"op":2,"by":{"0":"32","3":"11"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"136 S. Ct. 390","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"0":"19","3":"18"}},{"t":"case","label":"Oetjen v. Central Leather Co.","cite":"246 U.S. 297","y":1918,"id":"scdb/1917-085","sc":1,"sum":"The court notices judicially that the Government of the United States recognized the Government of Carranza as the de facto government of the Republic of Mexico, on October 19, 1915, and as the fie jure government on August 31, 1917.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Permanent Mission of India to the United Nations v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"op":1,"sum":"Noting our consistent practice of interpreting the FSIA in keeping with “international law at the time of the FSIA’s enactment” and looking to the contemporary Restatement for guidance.","sumSrc":"opinion","by":{"0":"14, 15, 23","1":"15","3":"7"}},{"t":"case","label":"Quackenbush v. Allstate Insurance Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"0":"47","3":"23"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Community","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"op":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"39, 43","2":"51","3":"11"}},{"t":"case","label":"Republic of Argentina v. NML Capital, Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"0":"48, 49","1":"6, 31, 32","2":"passim"}},{"t":"case","label":"Republic of Argentina v. Weltover","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"0":"23","3":"7"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"op":3,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"16, 17, 19, 46","1":"12","2":"13, 33","3":"14, 16"}},{"t":"case","label":"Republic of Philippines v. Pimentel","cite":"553 U.S. 851","y":2008,"id":"2007/06-1204","sc":1,"sum":"Such a required party must be joined to the suit if it is \"feasible,\" and the Court ruled that the government's inclusion was feasible in this case. The Court sent the case back to the district court with instructions to dismiss the interpleader action. Justice Anthony Kennedy delivered the opinion of the Court in which Justices John Paul Stevens and David Souter concurred in part and dissented in part.","sumSrc":"Oyez","by":{"0":"44","2":"52"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32, 39","1":"19","3":"11"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Rukoro v. Federal Republic of Germany","cite":"363 F. Supp. 3d 436","y":2019,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/363/436/","by":{"0":"35","1":"27"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"ar":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"0":"passim","1":"19","2":"51","3":"6, 7, 10, 11"}},{"t":"case","label":"Sarei v. Rio Tinto, PLC","cite":"550 F.3d 822","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/550/822/","by":{"0":"47, 48"}},{"t":"case","label":"Scalin v. Société Nationale des Chemins de Fer Français","cite":"2018 WL 1469015","y":2018,"court":"N.D. Ill. Mar. 26","by":{"0":"34"}},{"t":"case","label":"Siderman de Blake v. Republic of Argentina","cite":"965 F.2d 699","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/965/699/","sum":"Holding expropriation exception did not abrogate immunity for Argentine military junta’s alleged anti-Semitic campaign of violence, torture, and expropriation of property from its own nationals.","sumSrc":"brief:0","by":{"0":"18"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"812 F.3d 127","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/812/127/","op":1,"sum":"Noting that the FSIA provides “no avenue by which to bring claims for personal injury or death” caused by genocide abroad.","sumSrc":"brief:0","by":{"0":"20, 21, 30, 44, 48","1":"5, 13, 14, 18, 20","2":"26, 33"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"39, 44, 45, 50","1":"19, 26","2":"50, 51"}},{"t":"case","label":"T-Mobile South, LLC v. City of Roswell","cite":"574 U.S. 293","y":2015,"id":"2014/13-975","sc":1,"sum":"The Court held that the Telecommunications Act of 1996 does not require localities to provide reasons for their denial of construction applications in the written denial notification as long as the reasons appear in some other sufficiently clear written record.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"op":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23","1":"17"}},{"t":"case","label":"Timberlane Lumber Co. v. Bank of America","cite":"549 F.2d 597","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/549/597/","by":{"0":"43"}},{"t":"case","label":"Ungaro-Benages v. Dresdner Bank AG","cite":"379 F.3d 1227","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/379/1227/","by":{"0":"43, 47, 48","3":"22"}},{"t":"case","label":"United States v. Belmont","cite":"301 U.S. 324","y":1937,"id":"1900-1940/301us324","sc":1,"op":1,"ar":1,"sum":"Justice Sutherland argued for a unanimous Court that different kinds of treaties existed which did not require Senate approval, but nonetheless overrode state statutes. \"Plainly, the external powers of the United States are to be exercised without regard to state laws or policies,\" he reasoned.","sumSrc":"Oyez","by":{"0":"18","1":"10"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"48","1":"22","2":"39, 48"}},{"t":"case","label":"Whitman v. American Trucking Associations","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"usc","label":"22 U.S.C. § 2370","url":"https://www.law.cornell.edu/uscode/text/22/2370","subs":["(e)(2)","(e)(1)"],"stext":{"head":"§2370. Prohibitions against furnishing assistance","paras":[[0,"(a) Cuba; embargo on all trade"],[0,"(1) No assistance shall be furnished under this chapter to the present government of Cuba. As an additional means of implementing and carrying into effect the policy of the preceding sentence, the President is authorized to establish and maintain a total embargo upon all trade between the United States and Cuba."],[0,"(2) Except as may be deemed necessary by the President in the interest of the United States, no assistance shall be furnished under this chapter to any government of Cuba, nor shall Cuba be entitled to receive any quota authorizing the importation of Cuban sugar into the United States or to receive any other benefit under any law of the United States, until the President determines that such government has taken appropriate steps according to international law standards to return to United States citizens, and to entities not less than 50 per centum beneficially owned by United States citizens, or to provide equitable compensation to such citizens and entities for property taken from such citizens and entities on or after January 1, 1959, by the Government of Cuba."],[0,"(b) Repealed. Pub. L. 97–113, title VII, §734(a)(1), Dec. 29, 1981, 95 Stat. 1560"],[0,"(c) Indebtedness of foreign country to United States citizen or person"],[0,"No assistance shall be provided under this chapter to the government of any country which is indebted to any United States citizen or person for goods or services furnished or ordered where (i) such citizen or person has exhausted available legal remedies, which shall include arbitration, or (ii) the debt is not denied or contested by such government, or (iii) such indebtedness arises under an unconditional guaranty of payment given by such government, or any predecessor government, directly or indirectly, through any controlled entity: Provided, That the President does not find such action contrary to the national security."],[0,"(d) Productive enterprises competing with United States enterprise; conditions on assistance; import controls; waiver of restriction by President"],[0,"No assistance shall be furnished on a loan basis under part I of subchapter I of this chapter for construction or operation of any productive enterprise in any country where such enterprise will compete with United States enterprise unless such country has agreed that it will establish appropriate procedures to prevent the exportation for use or consumption in the United States of more than twenty per centum of the annual production of such facility during the life of the loan. In case of failure to implement such agreement by the other contracting party, the President is authorized to establish necessary import controls to effectuate the agreement. The restrictions imposed by or pursuant to this subsection may be waived by the President where he determines that such waiver is in the national security interest."],[0,"(e) Nationalization, expropriation or seizure of property of United States citizens, or taxation or other exaction having same effect; failure to compensate or to provide relief from taxes, exactions, or conditions; report on full value of property by Foreign Claims Settlement Commission; act of state doctrine"],[0,"(1) The President shall suspend assistance to the government of any country to which assistance is provided under this chapter or any other Act when the government of such country or any government agency or subdivision within such country on or after January 1, 1962—"],[1,"(A) has nationalized or expropriated or seized ownership or control of property owned by any United States citizen or by any corporation, partnership, or association not less than 50 per centum beneficially owned by United States citizens, or"],[1,"(B) has taken steps to repudiate or nullify existing contracts or agreements with any United States citizen or any corporation, partnership, or association not less than 50 per centum beneficially owned by United States citizens, or"],[1,"(C) has imposed or enforced discriminatory taxes or other exactions, or restrictive maintenance or operational conditions, or has taken other actions, which have the effect of nationalizing, expropriating, or otherwise seizing ownership or control of property so owned,"],[0,"and such country, government agency, or government subdivision fails within a reasonable time (not more than six months after such action, or, in the event of a referral to the Foreign Claims Settlement Commission of the United States within such period as provided herein, not more than twenty days after the report of the Commission is received) to take appropriate steps, which may include arbitration, to discharge its obligations under international law toward such citizen or entity, including speedy compensation for such property in convertible foreign exchange, equivalent to the full value thereof, as required by international law, or fails to take steps designed to provide relief from such taxes, exactions, or conditions, as the case may be; and such suspension shall continue until the President is satisfied that appropriate steps are being taken, and provisions of this subsection shall not be waived with respect to any country unless the President determines and certifies that such a waiver is important to the national interests of the United States. Such certification shall be reported immediately to Congress."],[0,"Upon request of the President (within seventy days after such action referred to in subparagraphs (A), (B), or (C) of this paragraph, the Foreign Claims Settlement Commission of the United States (established pursuant to Reorganization Plan No. 1 of 1954, 68 Stat. 1279) is hereby authorized to evaluate expropriated property, determining the full value of any property nationalized, expropriated, or seized, or subjected to discriminatory or other actions as aforesaid, for purposes of this subsection and to render an advisory report to the President within ninety days after such request. Unless authorized by the President, the Commission shall not publish its advisory report except to the citizen or entity owning such property. There is hereby authorized to be appropriated such amount, to remain available until expended, as may be necessary from time to time to enable the Commission to carry out expeditiously its functions under this subsection."],[0,"(2) Notwithstanding any other provision of law, no court in the United States shall decline on the ground of the federal act of state doctrine to make a determination on the merits giving effect to the principles of international law in a case in which a claim of title or other rights to property is asserted by any party including a foreign state (or a party claiming through such state) based upon (or traced through) a confiscation or other taking after January 1, 1959, by an act of that state in violation of the principles of international law, including the principles of compensation and the other standards set out in this subsection: Provided, That this subparagraph shall not be applicable (1) in any case in which an act of a foreign state is not contrary to international law or with respect to a claim of title or other right to property acquired pursuant to an irrevocable letter of credit of not more than 180 days duration issued in good faith prior to the time of the confiscation or other taking, or (2) in any case with respect to which the President determines that application of the act of state doctrine is required in that particular case by the foreign policy interests of the United States and a suggestion to this effect is filed on his behalf in that case with the court."],[0,"(f) Prohibition against assistance to Communist countries; conditions for waiver of restriction by President; enumeration of Communist countries; removal from application of provisions; preconditions"],[0,"(1) No assistance shall be furnished under this chapter, (except section 2174(b) of this title) to any Communist country. This restriction may not be waived pursuant to any authority contained in this chapter unless the President finds and promptly reports to Congress that: (A) such assistance is vital to the security of the United States; (B) the recipient country is not controlled by the international Communist conspiracy; and (C) such assistance will further promote the independence of the recipient country from international communism. For the purposes of this subsection, the phrase \"Communist country\" includes specifically, but is not limited to, the following countries:"],[1,"Democratic People's Republic of Korea,"],[1,"People's Republic of China,"],[1,"Republic of Cuba,"],[1,"Socialist Republic of Vietnam,"],[1,"Tibet,1"],[0,"(2) Notwithstanding the provisions of paragraph (1) of this subsection, the President may remove a country, for such period as the President determines, from the application of this subsection, and other provisions which reference this subsection, if the President determines and reports to the Congress that such action is important to the national interest of the United States. It is the sense of the Congress that when consideration is given to authorizing assistance to a country removed from the application of this subsection, one of the factors to be weighed, among others, is whether the country in question is giving evidence of fostering the establishment of a genuinely democratic system, with respect for internationally recognized human rights."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2370?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2370. Prohibitions against furnishing assistance","tname":"Foreign Relations and Intercourse","by":{"0":"26","1":"7, 16","2":"31, 31, 30, 31, 32"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"0":"46"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"head":"§1350. Alien's action for tort","tname":"Judiciary and Judicial Procedure","by":{"0":"39","2":"50"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","stext":{"head":"§1602. Findings and declaration of purpose","paras":[[0,"The Congress finds that the determination by United States courts of the claims of foreign states to immunity from the jurisdiction of such courts would serve the interests of justice and would protect the rights of both foreign states and litigants in United States courts. Under international law, states are not immune from the jurisdiction of foreign courts insofar as their commercial activities are concerned, and their commercial property may be levied upon for the satisfaction of judgments rendered against them in connection with their commercial activities. Claims of foreign states to immunity should henceforth be decided by courts of the United States and of the States in conformity with the principles set forth in this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1602?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1602. Findings and declaration of purpose","tname":"Judiciary and Judicial Procedure","by":{"0":"32, 33"}},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","by":{"0":"46"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"0":"15, 46"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(3)","(a)(5)","(A)","(2)","(h)","(h)(2)(A)","(h)(2)(B)(ii)","(h)(3)(B)(i)","(h)(3)(C)","(h)(1)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"0":"46, 1, 16, 25, 31","2":"34, passim, 2, passim, 2, 14, 15, 33, 14, 14","3":"3, 9, 13, 13"}},{"t":"usc","label":"28 U.S.C. § 1605A","url":"https://www.law.cornell.edu/uscode/text/28/1605A","subs":["(a)(2)(A)(ii)","(a)(2)(A)(iii)"],"stext":{"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","paras":[[0,"(a) In General.—"],[1,"(1) No immunity.—A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case not otherwise covered by this chapter in which money damages are sought against a foreign state for personal injury or death that was caused by an act of torture, extrajudicial killing, aircraft sabotage, hostage taking, or the provision of material support or resources for such an act if such act or provision of material support or resources is engaged in by an official, employee, or agent of such foreign state while acting within the scope of his or her office, employment, or agency."],[1,"(2) Claim heard.—The court shall hear a claim under this section if—"],[2,"(A)(i)(I) the foreign state was designated as a state sponsor of terrorism at the time the act described in paragraph (1) occurred, or was so designated as a result of such act, and, subject to subclause (II), either remains so designated when the claim is filed under this section or was so designated within the 6-month period before the claim is filed under this section; or"],[2,"(II) in the case of an action that is refiled under this section by reason of section 1083(c)(2)(A) of the National Defense Authorization Act for Fiscal Year 2008 or is filed under this section by reason of section 1083(c)(3) of that Act, the foreign state was designated as a state sponsor of terrorism when the original action or the related action under section 1605(a)(7) (as in effect before the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) was filed;"],[2,"(ii) the claimant or the victim was, at the time the act described in paragraph (1) occurred—"],[3,"(I) a national of the United States;"],[3,"(II) a member of the armed forces; or"],[3,"(III) otherwise an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment; and"],[2,"(iii) in a case in which the act occurred in the foreign state against which the claim has been brought, the claimant has afforded the foreign state a reasonable opportunity to arbitrate the claim in accordance with the accepted international rules of arbitration; or"],[2,"(B) the act described in paragraph (1) is related to Case Number 1:00CV03110 (EGS) in the United States District Court for the District of Columbia."],[0,"(b) Limitations.—An action may be brought or maintained under this section if the action is commenced, or a related action was commenced under section 1605(a)(7) (before the date of the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) not later than the latter of—"],[1,"(1) 10 years after April 24, 1996; or"],[1,"(2) 10 years after the date on which the cause of action arose."],[0,"(c) Private Right of Action.—A foreign state that is or was a state sponsor of terrorism as described in subsection (a)(2)(A)(i), and any official, employee, or agent of that foreign state while acting within the scope of his or her office, employment, or agency, shall be liable to—"],[1,"(1) a national of the United States,"],[1,"(2) a member of the armed forces,"],[1,"(3) an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment, or"],[1,"(4) the legal representative of a person described in paragraph (1), (2), or (3),"],[0,"for personal injury or death caused by acts described in subsection (a)(1) of that foreign state, or of an official, employee, or agent of that foreign state, for which the courts of the United States may maintain jurisdiction under this section for money damages. In any such action, damages may include economic damages, solatium, pain and suffering, and punitive damages. In any such action, a foreign state shall be vicariously liable for the acts of its officials, employees, or agents."],[0,"(d) Additional Damages.—After an action has been brought under subsection (c), actions may also be brought for reasonably foreseeable property loss, whether insured or uninsured, third party liability, and loss claims under life and property insurance policies, by reason of the same acts on which the action under subsection (c) is based."],[0,"(e) Special Masters.—"],[1,"(1) In general.—The courts of the United States may appoint special masters to hear damage claims brought under this section."],[1,"(2) Transfer of funds.—The Attorney General shall transfer, from funds available for the program under section 1404C of the Victims of Crime Act of 1984 (42 U.S.C. 10603c),1 to the Administrator of the United States district court in which any case is pending which has been brought or maintained under this section such funds as may be required to cover the costs of special masters appointed under paragraph (1). Any amount paid in compensation to any such special master shall constitute an item of court costs."],[0,"(f) Appeal.—In an action brought under this section, appeals from orders not conclusively ending the litigation may only be taken pursuant to section 1292(b) of this title."],[0,"(g) Property Disposition.—"],[1,"(1) In general.—In every action filed in a United States district court in which jurisdiction is alleged under this section, the filing of a notice of pending action pursuant to this section, to which is attached a copy of the complaint filed in the action, shall have the effect of establishing a lien of lis pendens upon any real property or tangible personal property that is—"],[2,"(A) subject to attachment in aid of execution, or execution, under section 1610;"],[2,"(B) located within that judicial district; and"],[2,"(C) titled in the name of any defendant, or titled in the name of any entity controlled by any defendant if such notice contains a statement listing such controlled entity."],[1,"(2) Notice.—A notice of pending action pursuant to this section shall be filed by the clerk of the district court in the same manner as any pending action and shall be indexed by listing as defendants all named defendants and all entities listed as controlled by any defendant."],[1,"(3) Enforceability.—Liens established by reason of this subsection shall be enforceable as provided in chapter 111 of this title."],[0,"(h) Definitions.—For purposes of this section—"],[1,"(1) the term \"aircraft sabotage\" has the meaning given that term in Article 1 of the Convention for the Suppression of Unlawful Acts Against the Safety of Civil Aviation;"],[1,"(2) the term \"hostage taking\" has the meaning given that term in Article 1 of the International Convention Against the Taking of Hostages;"],[1,"(3) the term \"material support or resources\" has the meaning given that term in section 2339A of title 18;"],[1,"(4) the term \"armed forces\" has the meaning given that term in section 101 of title 10;"],[1,"(5) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(6) the term \"state sponsor of terrorism\" means a country the government of which the Secretary of State has determined, for purposes of section 6(j) of the Export Administration Act of 1979 (50 U.S.C. App. 2405(j)),1 section 620A of the Foreign Assistance Act of 1961 (22 U.S.C. 2371), section 40 of the Arms Export Control Act (22 U.S.C. 2780), or any other provision of law, is a government that has repeatedly provided support for acts of international terrorism; and"],[1,"(7) the terms \"torture\" and \"extrajudicial killing\" have the meaning given those terms in section 3 of the Torture Victim Protection Act of 1991 (28 U.S.C. 1350 note)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605A?type=usc&year=mostrecent&link-type=html"},"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"0":"31","2":"16, 42","3":"9"}},{"t":"usc","label":"28 U.S.C. § 1605B","url":"https://www.law.cornell.edu/uscode/text/28/1605B","by":{"0":"31"}},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","stext":{"head":"§1606. Extent of liability","paras":[[0,"As to any claim for relief with respect to which a foreign state is not entitled to immunity under section 1605 or 1607 of this chapter, the foreign state shall be liable in the same manner and to the same extent as a private individual under like circumstances; but a foreign state except for an agency or instrumentality thereof shall not be liable for punitive damages; if, however, in any case wherein death was caused, the law of the place where the action or omission occurred provides, or has been construed to provide, for damages only punitive in nature, the foreign state shall be liable for actual or compensatory damages measured by the pecuniary injuries resulting from such death which were incurred by the persons for whose benefit the action was brought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1606?type=usc&year=mostrecent&link-type=html"},"head":"§1606. Extent of liability","tname":"Judiciary and Judicial Procedure","by":{"0":"48","1":"3, 31","2":"49","3":"21, 23"}},{"t":"case","label":"Brief of U.S. as Amicus Curiae, Von Saher v. Norton Simon Museum of Art at Pasadena","cite":"135 S. Ct. 1158","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1158/","sc":1,"op":4,"by":{"0":"54, 55"}},{"t":"case","label":"Concerning Application of the Convention on the Prevention and Punishment of the Crime of Genocide (Bosnia & Herzegovina v. Serbia & Montenegro)","cite":"2007 I.C.J. 43","url":"https://www.courtlistener.com/c/I.C.J./2007/43/","by":{"0":"35, 36"}},{"t":"case","label":"Jurisdictional Immunities of the State (Germany v. Italy; Greece intervening), Judgment","cite":"2012 I.C.J. 99","url":"https://www.courtlistener.com/c/I.C.J./2012/99/","op":2,"by":{"0":"32, 33"}},{"t":"case","label":"Altmann v. Republic of Austria","cite":"317 F.3d 954","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/954/","by":{"1":"13","2":"12–13, 25"}},{"t":"case","label":"American Ins. Ass’n v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"op":1,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Baker Botts L. L. P. v. Asarco LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Banco Nacional de Cuba v. Farr","cite":"243 F. Supp. 957","y":1965,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./243/957/","by":{"1":"16"}},{"t":"case","label":"Bank Tejarat v. Varsho-Saz","cite":"723 F. Supp. 516","y":1989,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./723/516/","by":{"1":"17"}},{"t":"case","label":"Canada Malting Co. v. Paterson S.S., Ltd.","cite":"285 U.S. 413","y":1932,"id":"scdb/1931-048","sc":1,"sum":"1. In a suit in admiralty between foreigners it is ordinarily within the discretion of the District Court to refuse to retain jurisdiction; and the exercise of its discretion will not be disturbed unless abused.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Comparelli v. Republica Bolivariana De Venezuela","cite":"891 F.3d 1311","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1311/","by":{"1":"17"}},{"t":"case","label":"Dreyfus v. Von Finck","cite":"534 F.2d 26","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/534/26/","by":{"1":"19"}},{"t":"case","label":"Erlenbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 16, 17"}},{"t":"case","label":"Hernandez v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"1":"26, 27"}},{"t":"case","label":"Jafari v. Islamic Republic of Iran","cite":"539 F. Supp. 209","y":1982,"court":"E.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./539/209/","by":{"1":"17"}},{"t":"case","label":"Medellin v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"NCAA v. Smith","cite":"525 U.S. 459","y":1999,"id":"1998/98-84","sc":1,"sum":"The Court held that dues payments from recipients of federal funds do not suffice to subject the NCAA to suit under Title IX.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"National City Bank v. Republic of China","cite":"348 U.S. 356","y":1955,"id":"scdb/1954-035","sc":1,"sum":"The counterclaims should not have been dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Perez v. Chase Manhattan Bank, N.A.","cite":"463 N.E.2d 5","y":1984,"url":"https://www.courtlistener.com/c/N.E.2d/463/5/","by":{"1":"17"}},{"t":"case","label":"Persinger v. Islamic Republic of Iran","cite":"729 F.2d 835","y":1984,"url":"https://www.courtlistener.com/c/F.2d/729/835/","by":{"1":"29"}},{"t":"case","label":"Saudi Arabia v. Nelson","cite":"507 U.S. 349","y":1993,"id":"1992/91-522","sc":1,"op":3,"sum":"The Nelsons' action is not \"based upon a commercial activity\" within the meaning of the first clause of § 1605(a)(2), and the Act therefore confers no jurisdiction over their suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Underhill v. Hernandez","cite":"168 U.S. 250","y":1897,"id":"scdb/1897-017","sc":1,"sum":"Hernandez was in command of a revolutionary army in Venezuela when an engagement took place with the government forces which resulted in the defeat of the latter, and the occupation of Bolivar by the former. Underhill was living in Bolivar, where he had constructed a waterworks system for the' city under a contract with the government, and carried on a machinery repair business. He applied for a passport to leave …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"op":2,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Victory Transp. Inc. v. Comisaria Gen. de Abastecimientos y Transportes","cite":"336 F.2d 354","y":1964,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/336/354/","by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 114-308","url":"https://www.govinfo.gov/link/plaw/114/public/308","by":{"1":"25","2":"passim"}},{"t":"law","label":"Holocaust Victims Redress Act, Pub. L. No. 105-158","url":"https://www.govinfo.gov/link/plaw/105/public/158","by":{"1":"25","2":"passim"}},{"t":"case","label":"Agudas Chasidei Chabad v. Russian Fed’n","cite":"528 F.3d 934","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/528/934/","by":{"2":"42"}},{"t":"case","label":"Balintulo v. Daimler AG","cite":"727 F.3d 174","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/727/174/","by":{"2":"50"}},{"t":"case","label":"Bank of Augusta v. Earle","cite":"38 U.S. 519","y":1839,"id":"scdb/1839-050","sc":1,"sum":"An action was instituted in the Circuit Court of the United States for the District of Ala-. bama, by the Bank of Augusta, Georgia, against the defendant, a citizen of Alabama, on bills of exchange drawn at Mobile, Alabama, on New York, which had been protested for non-payment, and returned to Mobile. The bill was made and endorsed for the purpose of being discounted by.the agent of the bank, who had funds in his …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Bernstein v. N. V. Nederlandsche-Amerikaansche Stoomvaart-Maatschappij","cite":"210 F.2d 375","y":1954,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/210/375/","by":{"2":"22"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"ar":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"8, 11, 17, 32, 33","3":"4, 5, 8, 13, 15"}},{"t":"case","label":"Cassirer v. Kingdom of Spain","cite":"616 F.3d 1019","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/1019/","by":{"2":"12, 25, 27","3":"20"}},{"t":"case","label":"City & Cnty. of San Francisco v. Sheehan","cite":"135 S. Ct. 1765","y":2015,"id":"2014/13-1412","sc":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Colautti v. Franklin","cite":"439 U.S. 379","y":1979,"id":"1978/77-891","sc":1,"sum":"Section 5 (a) of the Pennsylvania Abortion Control Act requires every person who performs an abortion to make a determination, \"based on his experience, judgment or professional competence,\" that the fetus is not viable. If such person determines that the fetus \"is viable,\" or \"if there is sufficient reason to believe that the fetus may be viable,\" then he must exercise the same care to preserve the fetus' life and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Colo. River Water Conserv. Dist v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45, 46, 47, 52"}},{"t":"case","label":"County of Allegheny v. Frank Mashuda Co.","cite":"360 U.S. 185","y":1959,"id":"1958/347","sc":1,"sum":"No exceptional circumstances justifying abstention appear in this case, and the District Court should have adjudicated the claim. Pp. 186-198. = (a) The doctrine of abstention, under which a district court may decline to exercise or postpone the exercise of its jurisdiction, is an extraordinary and narrow exception to the duty of a districV court to adjudicate a controversy properly before it.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"de Csepel v. Republic of Hung.","cite":"808 F. Supp. 2d 113","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/808/113/","by":{"2":"13, 25"}},{"t":"case","label":"de Csepel v. Republic of Hung.","cite":"2016 U.S. Dist. LEXIS 32111","y":2016,"court":"D.D.C. Mar. 14","by":{"2":"13, 25"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"29","3":"6"}},{"t":"case","label":"Gross v. German Found. Indus. Initiative","cite":"456 F.3d 363","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/456/363/","by":{"2":"46"}},{"t":"case","label":"IIT v. Vencap, Ltd.","cite":"519 F.2d 1001","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/519/1001/","by":{"2":"50"}},{"t":"case","label":"Int’l Bhd. of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Kiobel v. Royal Dutch Petrol. Co.","cite":"621 F.3d 111","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/621/111/","by":{"2":"50"}},{"t":"case","label":"Malewicz v. City of Amsterdam","cite":"362 F. Supp. 2d 298","y":2005,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/362/298/","op":1,"ar":1,"by":{"2":"13, 25","3":"12, 14"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52"}},{"t":"case","label":"Royal & Sun All. Ins. Co. of Can. v. Century Int’l Arms, Inc.","cite":"466 F.3d 88","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/466/88/","by":{"2":"46, 47, 53"}},{"t":"case","label":"S.D. Warren Co. v. Me. Bd. of Env’t Prot.","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"2":"11–12"}},{"t":"case","label":"Simon v. Republic of Hung.","cite":"911 F.3d 1172","y":2018,"url":"https://www.courtlistener.com/c/F.3d/911/1172/","by":{"2":"41"}},{"t":"case","label":"Societe Nationale Industrielle Aerospatiale v. United States Dist. Court for S. Dist.","cite":"482 U.S. 522","y":1987,"id":"1986/85-1695","sc":1,"sum":"The United States, France, and 15 other countries have acceded to the Hague Evidence Convention, which prescribes procedures by which a judicial authority in one contracting state may request evidence located in another. Plaintiffs brought suits (later consolidated) in Federal District Court for personal injuries resulting from the crash of an aircraft built and sold by petitioners, two corporations owned by France. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"United States v. First Nat’l Bank","cite":"234 U.S. 245","y":1914,"id":"scdb/1913-096","sc":1,"op":1,"ar":5,"sum":"The natural and usual signification of plain terms is to be adopted as the legislative meaning in the absence of clear showing that something else was meant.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"28, 29"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"law","label":"Justice for Uncompensated Survivors Today (JUST) Act, Pub. L. No. 115-171","url":"https://www.govinfo.gov/link/plaw/115/public/171","by":{"2":"23, 25, 26, 53"}},{"t":"rule","label":"Fed. R. Civ. P. 19","url":"https://www.law.cornell.edu/rules/frcp/rule_19","subs":["(b)"],"by":{"2":"52"}},{"t":"case","label":"Air Wisc. Airlines Corp. v. Hoeper","cite":"571 U.S. 237","y":2014,"id":"2013/12-315","sc":1,"sum":"The Court ruled that the Aviation and Transportation Security Act protects transportation officials from false statements, as long as the statements are not materially false within the ATSA context.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"New Prime, Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"op":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"7"}},{"t":"case","label":"Von Saher v. Norton Simon Museum of Art at Pasadena","cite":"592 F.3d 954","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/592/954/","by":{"3":"21, 25"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"24"}},{"t":"usc","label":"22 U.S.C. § 2459","url":"https://www.law.cornell.edu/uscode/text/22/2459","by":{"3":"12"}}]};